{
  "dashboard": {
    "title": "DR 场景覆盖率",
    "panels": [
      {
        "title": "场景验证状态",
        "type": "stat",
        "targets": [
          { "expr": "count(dr_scenario_status == 1)" }
        ]
      },
      {
        "title": "逾期演练",
        "type": "table",
        "targets": [
          { "expr": "time() - dr_scenario_last_drill_timestamp > dr_scenario_drill_interval" }
        ]
      },
      {
        "title": "RTO 达标率",
        "type": "gauge",
        "targets": [
          { "expr": "sum(dr_scenario_rto_achieved) / count(dr_scenario_rto_achieved) * 100" }
        ]
      }
    ]
  }
}
